def _contour_passes_size(contour, min_cable_area, min_length):
    (_cx, _cy), (rw, rh), _ang = cv2.minAreaRect(contour)
    return cv2.contourArea(contour) >= float(min_cable_area) and max(rw, rh) >= float(min_length)

_contour_length.code:
def _contour_length(contour):
    (_cx, _cy), (rw, rh), _ang = cv2.minAreaRect(contour)
    return float(max(rw, rh))

_contour_centroid.code:
def _contour_centroid(contour):
    m = cv2.moments(contour)
    if m["m00"] == 0:
        x, y, bw, bh = cv2.boundingRect(contour)
        return np.array([x + bw * 0.5, y + bh * 0.5], dtype=np.float64)
    return np.array([m["m10"] / m["m00"], m["m01"] / m["m00"]], dtype=np.float64)

overlay_masks.code:
def overlay_masks(image, masks, color=(0, 255, 0), alpha=0.45, scores=None):
    """Draw filled masks on a BGR image copy; optional conf text at centroid."""
    try:
        out = image.copy()
        if not masks:
            return out
        overlay = out.copy()
        for idx, mask in enumerate(masks):
            m = np.asarray(mask)
            if m.shape[:2] != out.shape[:2]:
                m = cv2.resize(m, (out.shape[1], out.shape[0]), interpolation=cv2.INTER_NEAREST)
            overlay[m > 0] = color
            if scores is not None and idx < len(scores):
                ys, xs = np.where(m > 0)
                if len(xs) > 0:
                    cx, cy = int(xs.mean()), int(ys.mean())
                    cv2.putText(
                        overlay,
                        f"{scores[idx]:.2f}",
                        (cx, max(0, cy - 5)),
                        cv2.FONT_HERSHEY_SIMPLEX,
                        0.5,
                        (255, 255, 255),
                        1,
                        cv2.LINE_AA,
                    )
        return cv2.addWeighted(overlay, alpha, out, 1.0 - alpha, 0)
    except Exception:
        try:
            return image.copy()
        except Exception:
            return image

