def pickup_points_for_masks(masks, fraction=0.5, offset_px=45.0, image=None):
    """Return list of (x, y) or None for each mask."""
    return [
        pickup_point(m, fraction=fraction, offset_px=offset_px, image=image)
        for m in (masks or [])
    ]
